import json,re,hashlib,difflib
from html.parser import HTMLParser
from collections import Counter
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text())
assert len(a)==len(s)==24
assert len({(x['code_id'],x['source_id']) for x in a})==24
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
class CheckHTML(HTMLParser):
 def handle_starttag(self, tag, attrs):
  assert tag in allowed, tag
  for k,v in attrs: assert k in {'rowspan','colspan'} and v.isdigit(), (k,v)
class Plain(HTMLParser):
 def __init__(self): super().__init__(convert_charrefs=True); self.out=[]
 def handle_data(self,data): self.out.append(data)
def text(xml):
 p=Plain(); p.feed(xml); return ''.join(p.out)
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert x[k]==y[k],(x['number'],k)
 for k in ['reason','review_notes']: assert isinstance(y[k],str) and y[k].strip()
 imp=y['substantive_impact']; assert imp['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']: assert len(imp[k])>=40,(x['number'],k)
 if x.get('benefit_check_required'): assert len(y['benefit_review'])>=100
 if y['status']=='retained_unchanged':
  assert y['proposed_xml'] is None and y['classification']=='retained_necessary'
  assert imp['classification']=='retained_necessary' and imp['effects']==[]
 else:
  assert y['status']=='rewrite_draft' and y['proposed_xml']
  CheckHTML().feed(y['proposed_xml'])
 for e in imp['effects']:
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for f,xml in [('source_quote',x['source_xml']),('proposed_quote',y['proposed_xml'])]:
   assert len(e[f])>=12 and e[f] in text(xml),(x['number'],f)
print('24 objets uniques ; identifiants et empreintes recopiés exactement ; champs et citations vérifiés.')
print('Statuts :',dict(Counter(x['status'] for x in a)))
print('Impacts :',dict(Counter(x['substantive_impact']['classification'] for x in a)))
for x,y in zip(s,a):
 if y['proposed_xml'] is not None:
  print('\\nRELECTURE FINALE DE LA PROPOSITION',y['number'])
  print(y['proposed_xml'])
  print('\\nDIFFERENCE EXACTE')
  print('\\n'.join(difflib.unified_diff(x['source_xml'].splitlines(),y['proposed_xml'].splitlines(),fromfile='source',tofile='proposition',lineterm='')))
print('\\nTous les autres corps restent intégralement ceux des sources par proposed_xml=null.')
PY"

